script:
# EXHAUSTIVE COMMENT: Loop through every row in the Stock Entry 'Items' child table
for item in doc.items:
    
    # EXHAUSTIVE COMMENT: Execute ONLY if there is NO Source Warehouse AND there IS a Target Warehouse
    if not item.s_warehouse and item.t_warehouse:
        
        if item.item_code:
            # Fetch the static valuation_rate directly from the Item Master database record
            fixed_rate = frappe.db.get_value("Item", item.item_code, "valuation_rate")
            
            # If a rate is successfully found in the Item Master, apply the override
            if fixed_rate:
                # Forcefully overwrite whatever rate the ERPNext standard engine calculated
                item.basic_rate = fixed_rate
                
                # Recalculate the total row amount using standard Python float() to respect the safe_exec sandbox
                item.amount = float(item.qty) * float(fixed_rate)

total_partner_comm = 0.0

for row in doc.items:
    comm_type = row.get("custom_commission_type")
    comm_val = frappe.utils.flt(row.get("custom_commission_rate__value") or 0.0)
    net_amt = frappe.utils.flt(row.get("net_amount") or 0.0)
    qty = frappe.utils.flt(row.get("qty") or 0.0)
    line_comm = 0.0

    if comm_type == "Percentage":
        line_comm = (net_amt * comm_val) / 100.0
    elif comm_type == "Per Unit/UOM":
        line_comm = qty * comm_val

    row.custom_commission_amount = line_comm
    total_partner_comm += line_comm


if total_partner_comm > 0:
    doc.total_commission = total_partner_comm
    doc.commission_rate = 0.0
elif frappe.utils.flt(doc.commission_rate or 0.0) > 0:
    doc.total_commission = (frappe.utils.flt(doc.net_total or 0.0) * frappe.utils.flt(doc.commission_rate or 0.0)) / 100.0

if doc.total_commission:
    doc.amount_eligible_for_commission = frappe.utils.flt(doc.net_total)

# Recalculate and validate consignment value
total_val = sum([flt(d.total_amount) for d in doc.packaging_items])
doc.consignment_total_value = total_val

# Validation 1: Returning Qty cannot exceed Inward Qty
for row in doc.packaging_items:
    if flt(row.returning_qty) > flt(row.inward_qty):
        frappe.throw(f"Row #{row.idx}: Returning Qty ({row.returning_qty}) cannot be greater than Inward Qty ({row.inward_qty}).")

# Validation 2: 50,000 threshold check for e-Waybill
if total_val > 50000:
    doc.ewaybill_required = 1
    if not doc.ewaybill_no:
        frappe.throw(
            title="GST Compliance Error",
            msg=f"Total Return Packaging Value is ₹{total_val:,.2f} (exceeds ₹50,000). "
                f"As per GST Rule 55, entering the e-Waybill Number is mandatory before submitting!"
        )
else:
    doc.ewaybill_required = 0

for row in doc.items:
    if row.item_code and row.batch_no:
        item_has_batch = frappe.db.get_value("Item", row.item_code, "has_batch_no")

        if item_has_batch:
            batch_exists = frappe.db.exists("Batch", row.batch_no)

            if not batch_exists:
                batch = frappe.new_doc("Batch")
                batch.batch_id = row.batch_no
                batch.item = row.item_code
                batch.insert(ignore_permissions=True)

# Server Script: purchase_order_re_approval
# DocType Event: After Save (Submitted Document)

if doc.docstatus == 1 and not doc.custom_reapproval_required:
    
    # Simple check on grand total variance
    db_grand_total = frappe.db.get_value("Purchase Order", doc.name, "grand_total")
    
    if db_grand_total and frappe.utils.flt(db_grand_total) != frappe.utils.flt(doc.grand_total):
        frappe.db.set_value("Purchase Order", doc.name, {
            "custom_reapproval_required": 1,
            "workflow_state": "Pending Re-Approval"
        })
        doc.custom_reapproval_required = 1
        doc.workflow_state = "Pending Re-Approval"

# Copy Header dimensions to Purchase Taxes and Charges

for tax in doc.taxes:
    if doc.cost_center:
        tax.cost_center = doc.cost_center

    if doc.unit:
        tax.unit = doc.unit

# Copy Header dimensions to Purchase Taxes and Charges

for tax in doc.taxes:
    if doc.cost_center:
        tax.cost_center = doc.cost_center

    if doc.unit:
        tax.unit = doc.unit

# Copy Header dimensions to Purchase Taxes and Charges

for tax in doc.taxes:
    if doc.cost_center:
        tax.cost_center = doc.cost_center

    if doc.unit:
        tax.unit = doc.unit

# Context: Server Script (DocType Event: Stock Entry / Purchase Receipt -> Before Submit)
# Purpose: Restrict inventory transactions (Inward, Outward, or Transfer) involving 
#          protected Warehouses strictly to the 2-3 whitelisted User IDs defined on the Warehouse master.

def enforce_warehouse_user_whitelist(doc):
    # Guard Clause: Ensure valid document object and child items table
    if not doc:
        return

    items = doc.get("items") or []
    if not items:
        return

    current_user = frappe.session.user
    # Optional Administrator override bypass (remove if Administrator must also be blocked)
    if current_user == "Administrator":
        return

    # Step 1: Collect all unique Warehouses referenced in the current transaction rows
    involved_warehouses = set()
    for row in items:
        # Check standard Warehouse fields across Stock Entry, Purchase Receipt, Delivery Note, etc.
        for wh_field in ("s_warehouse", "t_warehouse", "warehouse", "from_warehouse", "rejected_warehouse"):
            wh_val = row.get(wh_field)
            if wh_val and isinstance(wh_val, str):
                involved_warehouses.add(wh_val.strip())

    if not involved_warehouses:
        return

    # Step 2: Query Warehouse master configuration for all involved Warehouses in a single batch
    warehouse_configs = frappe.get_all(
        "Warehouse",
        filters={
            "name": ["in", list(involved_warehouses)],
            "custom_restrict_transaction_users": 1
        },
        fields=["name", "custom_authorized_user_ids"]
    )

    if not warehouse_configs:
        return

    # Build lookup dictionary of restricted warehouses -> set of allowed user IDs
    restricted_wh_map = {}
    for wh in warehouse_configs:
        raw_users = wh.get("custom_authorized_user_ids") or ""
        allowed_set = {
            u.strip().lower()
            for u in raw_users.split(",")
            if u and u.strip()
        }
        restricted_wh_map[wh.get("name")] = allowed_set

    # Step 3: Validate each child item row against the Warehouse whitelist
    for row in items:
        row_warehouses = []
        for wh_field in ("s_warehouse", "t_warehouse", "warehouse", "from_warehouse", "rejected_warehouse"):
            wh_val = row.get(wh_field)
            if wh_val and wh_val.strip() in restricted_wh_map:
                row_warehouses.append(wh_val.strip())

        for protected_wh in set(row_warehouses):
            allowed_users = restricted_wh_map.get(protected_wh, set())

            if current_user.lower() not in allowed_users:
                allowed_display = ", ".join(sorted(allowed_users)) if allowed_users else "None Configured"
                frappe.throw(
                    msg=(
                        f"<b>Row #{row.idx}: Unauthorized Warehouse Transaction</b><br>"
                        f"Warehouse <b>{frappe.bold(protected_wh)}</b> is restricted to designated custodians.<br><br>"
                        f"Current User: <b>{frappe.bold(current_user)}</b><br>"
                        f"Authorized User IDs: <b>{allowed_display}</b><br><br>"
                        f"Please route this document to an authorized custodian for submission."
                    ),
                    title="Warehouse Access Restricted"
                )

# Execute validation
enforce_warehouse_user_whitelist(doc)

# Ensure Sales Invoice Line Item (row.gst_hsn_code) is always the single source of truth
# Overwrites dummy '000000' placeholders on the line item with the valid Item Master HSN
for row in (doc.get("items") or []):
    raw_hsn = str(row.get("gst_hsn_code") or "").strip()
    is_dummy_zeros = bool(raw_hsn and raw_hsn.replace("0", "") == "")
    if (not raw_hsn or is_dummy_zeros or raw_hsn in ("-", "NA", "N/A")) and row.get("item_code"):
        master_hsn = frappe.db.get_value("Item", row.get("item_code"), "gst_hsn_code")
        if master_hsn and str(master_hsn).strip().replace("0", "") != "":
            row.gst_hsn_code = str(master_hsn).strip()
